    );
  }

  if (block.kind === 'network')
    return (
      <div className="printer-found">
        <p className="printer-found-caption">FOUND ON YOUR NETWORK</p>
        {((block.printers ?? []) as NetworkPrinterInfo[]).map((printer) => (
          <div className="printer-row" key={printer.serial}>
