// Throwaway preview of the plug-in notice (not committed).
import { describe, it } from 'vitest';
import { renderToStaticMarkup } from 'react-dom/server';
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { MessageList } from './MessageList';
import { applyStaticTokens } from '../tokens';
import { Message } from '../state/store';
import type { PrinterBlock } from '../bridge/protocol';
import tokens from '../../../../../../../resources/jusprin/ui/design-tokens.json';

const message = (id: string, role: Message['role'], text: string): Message =>
  ({ id, role, state: 'complete', text, attempt: 1, lastSeq: 0 });

const noop = () => {};

function thread(installed: boolean) {
  const blocks: PrinterBlock[] = [{ id: 'b1', seq: 1, afterMessageId: 'm1', kind: 'plugin', installed }];
  return renderToStaticMarkup(
    <MessageList
      messages={[
        message('m1', 'assistant', 'To connect Bambu Lab A1 mini, JusPrin first needs Bambu’s network plug-in, which isn’t installed on this computer yet. Bambu Lab A1 mini already works for preparing prints.'),
        message('m2', 'user', 'Connect it'),
        message('m3', 'assistant', 'Bambu’s network plug-in still isn’t available here, so I can’t connect it right now.'),
      ]}
      attachments={[]}
      streamingMessageId={null}
      toolActivities={[]}
      builds={[]}
      exportedCopies={[]}
      physicalPrints={[]}
      changes={[]}
      printerBlocks={blocks}
      onUndoAdd={noop}
      onInstallPlugin={noop}
      answeredState={false}
      onRetry={noop}
      onToolDecision={noop}
      onToolCancel={noop}
      onSend={noop}
    />,
  );
}

describe('plugin notice preview', () => {
  it('writes a page', () => {
    const out = process.env.PREVIEW_OUT;
    if (!out) return;
    const css = readFileSync(resolve(__dirname, '../styles.css'), 'utf8');
    applyStaticTokens();
    const staticVars = document.documentElement.style.cssText;
    const semantic = (tokens as { semantic: Record<string, Record<string, Record<string, string>>> }).semantic;
    const varsFor = (mode: string) =>
      Object.entries(semantic[mode])
        .flatMap(([group, values]) => Object.entries(values).map(([name, value]) => `--${group}-${name}: ${value};`))
        .join('\n  ');
    const panel = (mode: string, width: number, installed: boolean) => `<figure><figcaption>${mode}, ${width}px, ${installed ? 'installed' : 'needed'}</figcaption>
<div class="dock ${mode}" style="width:${width}px"><div class="app"><div class="chat-content">${thread(installed)}</div></div></div></figure>`;
    writeFileSync(out, `<!doctype html><meta charset="utf-8"><title>Plug-in notice</title>
<style>
:root { ${varsFor('light')} ${staticVars} }
${css}
.dark { ${varsFor('dark')} }
body { background: #f2f2f2; font-family: system-ui, sans-serif; padding: 16px; margin: 0; }
.grid { display: flex; flex-wrap: wrap; gap: 16px; align-items: flex-start; }
figure { margin: 0; } figcaption { font-size: 12px; margin-bottom: 6px; }
.dock { height: 520px; border: 1px solid #bbb; background: var(--surface-subtle); overflow: hidden; }
.dock.dark { color: var(--text-primary); }
.dock .app { height: 100%; }
</style>
<div class="grid">${panel('light', 640, false)}${panel('dark', 640, false)}${panel('light', 360, false)}${panel('light', 640, true)}</div>`);
  });
});

